/**
 * Build-time codegen for the Swagger UI static assets.
 *
 * Reads the three required assets from `swagger-ui-dist` and
 * writes them into `backend/src/docs/swaggerUI.assets.ts` as
 * base64-encoded strings. The generated file is what
 * `swaggerUI.ts` imports at module load — so the bytes are part
 * of the compiled Function bundle, not files Vercel has to ship
 * separately.
 *
 * Why this exists: Vercel's function bundler (`@vercel/nft`)
 * follows `require()` / `import` graph edges when deciding what
 * to include in the deployment. Static files inside npm
 * packages (CSS, large JS bundles referenced only by
 * `fs.readFileSync`) are NOT included, because they're not part
 * of the import graph. We hit this with `swagger-ui-dist`: the
 * `swagger-ui.css`, `swagger-ui-bundle.js`, and
 * `swagger-ui-standalone-preset.js` files were not in the
 * Function payload, so a custom handler that read them from
 * disk crashed with ENOENT. `vercel.json#functions.includeFiles`
 * is the documented fix, but on the current Vercel account
 * config it caused the build itself to fail with an opaque
 * error — so we fall back to the more portable inlined approach.
 *
 * Trade-offs vs includeFiles:
 *   - The compiled Function bundle grows by ~1.6 MB
 *     (swagger-ui-bundle.js is the bulk of it). The current
 *     Function limit is 250 MB on Pro / 50 MB unzipped on
 *     Hobby; we're well under.
 *   - The generated file is committed to the repo (so the build
 *     is hermetic and the data is visible in code review). The
 *     script is idempotent — re-run it any time
 *     `swagger-ui-dist` is upgraded.
 *
 * Invocation: `node backend/scripts/inline-swagger-assets.js`
 * wired into the backend's `prebuild` npm script so it runs
 * before every `tsc`.
 */
'use strict';

const fs = require('fs');
const path = require('path');

const ASSETS = [
  {
    name: 'swagger-ui.css',
    contentType: 'text/css',
  },
  {
    name: 'swagger-ui-bundle.js',
    contentType: 'application/javascript',
  },
  {
    name: 'swagger-ui-standalone-preset.js',
    contentType: 'application/javascript',
  },
];

// swagger-ui-dist publishes its `absolute-path.js` and we read
// from its `__dirname` to find the static assets. That module
// resolves to the package root, so the assets are siblings.
const distRoot = path.dirname(require.resolve('swagger-ui-dist/absolute-path'));

const entries = ASSETS.map((asset) => {
  const filePath = path.join(distRoot, asset.name);
  const body = fs.readFileSync(filePath);
  return {
    name: asset.name,
    contentType: asset.contentType,
    base64: body.toString('base64'),
    sizeBytes: body.length,
  };
});

const out = `/**
 * AUTO-GENERATED by backend/scripts/inline-swagger-assets.js.
 * Do not edit by hand — re-run the script to regenerate.
 *
 * Each asset's bytes are embedded as a base64 string so they
 * ship inside the compiled Function bundle. The runtime handler
 * in swaggerUI.ts decodes them once at module load.
 */
export interface InlinedAsset {
  filename: string;
  contentType: string;
  sizeBytes: number;
  base64: string;
}

export const INLINED_SWAGGER_ASSETS: readonly InlinedAsset[] = [
${entries
  .map(
    (e) => `  {
    filename: ${JSON.stringify(e.name)},
    contentType: ${JSON.stringify(e.contentType)},
    sizeBytes: ${e.sizeBytes},
    base64: ${JSON.stringify(e.base64)},
  },`,
  )
  .join('\n')}
];
`;

// Write next to the consuming module so the import path is short.
const outDir = path.resolve(__dirname, '..', 'src', 'docs');
const outFile = path.join(outDir, 'swaggerUI.assets.ts');
fs.writeFileSync(outFile, out, 'utf8');

console.log(
  `[inline-swagger-assets] wrote ${entries.length} assets ` +
    `(${(entries.reduce((s, e) => s + e.sizeBytes, 0) / 1024).toFixed(1)} KB) ` +
    `to ${path.relative(process.cwd(), outFile)}`,
);
